import { spawn } from "node:child_process";
import { randomUUID } from "node:crypto";
const bridge = `${process.env.HOME}/.local/share/opik-cli-bridge/bridge.js`;
function resourceAttribute(name) {
    const raw = process.env.OTEL_RESOURCE_ATTRIBUTES || "";
    const match = raw
        .split(",")
        .map((part) => part.trim())
        .find((part) => part.startsWith(`${name}=`));
    return match ? match.slice(name.length + 1) : undefined;
}
function normalizeDeploymentEnvironment(value) {
    const env = String(value || "").trim().toLowerCase();
    if (!env)
        return "production";
    if (["prod", "production", "live", "macbook", "mac-mini", "lue-kube"].includes(env))
        return "production";
    if (["stage", "staging"].includes(env))
        return "staging";
    if (["dev", "development", "local", "test", "testing"].includes(env))
        return env === "test" ? "testing" : env;
    return env;
}
const deploymentEnvironment = normalizeDeploymentEnvironment(process.env.DEPLOYMENT_ENVIRONMENT ||
    process.env.DEPLOYMENT_ENV ||
    process.env.APP_ENV ||
    process.env.NODE_ENV ||
    resourceAttribute("deployment.environment"));
function send(event, envelope) {
    const child = spawn(process.execPath, [bridge, "--cli", "pi", "--event", event], {
        stdio: ["pipe", "ignore", "ignore"],
        detached: true,
    });
    child.stdin.end(JSON.stringify(envelope));
    child.unref();
}
export default function (pi) {
    let turnId = randomUUID();
    let model = "";
    pi.on("before_agent_start", (event, ctx) => {
        turnId = randomUUID();
        model = ctx.model ? `${ctx.model.provider}/${ctx.model.id}` : "";
        send("before_agent_start", {
            session_id: ctx.sessionManager.getSessionId() ?? "unknown",
            turn_id: turnId,
            cwd: ctx.cwd,
            has_prompt: Boolean(event.prompt),
            model,
            deployment_environment: deploymentEnvironment,
            environment: deploymentEnvironment,
        });
    });
    pi.on("agent_end", (event, ctx) => {
        const assistantMessages = event.messages.filter((m) => m.role === "assistant");
        const last = assistantMessages[assistantMessages.length - 1];
        const lastRecord = last;
        const usage = lastRecord?.usage;
        const metadata = lastRecord?.metadata;
        send("agent_end", {
            session_id: ctx.sessionManager.getSessionId() ?? "unknown",
            turn_id: turnId,
            cwd: ctx.cwd,
            has_output: Boolean(last),
            model,
            usage,
            token_budget_gate: metadata?.pi_token_budget_gate,
            deployment_environment: deploymentEnvironment,
            environment: deploymentEnvironment,
        });
    });
}
