// Install once as a process-wide preference and NEVER restore it on session
// dispose. `onBashTimeout` mutates a single package-global resolver, and its
// restore fns are not a real stack — restoring on every top-level dispose
// (/new, /fork, switchSession) reverted the global to the core kill policy,
// so a timed-out command was KILLED instead of detached until the next session
// re-activated this extension (and stacked disposes clobbered it to kill
// outright). The policy is idempotent — always the same detach closure — so
// re-installing on each activation and never restoring keeps auto-background
// reliably on. Regression: autobg-lifecycle.test.mjs.
if (isEnabled("bash")) {
  onBashTimeout((t) => ({ backgroundedJobId: t.background().id }));
}
// CACHE CRITICAL: these utility aliases must remain provider-visible but
// schema-deferred. Marking them alwaysLoad reintroduces the prompt-cache burst
// where background/listing schemas are billed every turn. They are discovered
// through the stable <deferred-tools> index and loaded through Anthropic
// `defer_loading` / `tool_reference`, matching Claude Code and Codex.
// Unified background-task tools (Claude Code task_id parity) over the core
// task-registry seam: one id space across background bash jobs AND background
// agent runs. These replace the bash-only BashOutput/KillShell. The bash log
// rendering (tail/head/all, status header) is preserved inside TaskOutput.
add("TaskOutput", {
  ...createTaskOutputToolDefinition(),
  deferLoading: true,
  replacesBuiltins: ["bash_output"],
});
add("TaskStop", {
  ...createTaskStopToolDefinition(),
  deferLoading: true,
  replacesBuiltins: ["bash_kill"],
});
add("TaskList", {
  ...createTaskListToolDefinition(),
